public List<GasResponseDTO> getTodayReadings() {
    LocalDateTime startOfToday = LocalDateTime.now().toLocalDate().atStartOfDay();
    LocalDateTime endOfToday = startOfToday.plusDays(1);

    // 1. Find All (Kif ma bghiti)
    return gasRepository.findAll().stream()
            // 2. Filter (Java Logic)
            .filter(g -> {
                if (g.getCreatedAt() == null) return false;
                return !g.getCreatedAt().isBefore(startOfToday) && 
                        g.getCreatedAt().isBefore(endOfToday);
            })
            // 3. Map using Builder Pattern
            .map(gas -> GasResponseDTO.builder()
                    .id(gas.getId().toString())
                    .value(gas.getValue()) // awla gas.getReading() 3la hsab entity dyalk
                    .createdAt(gas.getCreatedAt())
                    .build())
            .toList(); // Wella .collect(Collectors.toList()) ila 3ndk Java 9dim

public List<GasResponseDTO> getConsumedGasBetweenDates(LocalDateTime start, LocalDateTime end) {

    // 1. Njibo kolchi mn Gas Repository
    List<Gas> allGas = gasRepository.findAll();

    return allGas.stream()
            .filter(g -> {
                if (g.getCreatedAt() == null) return false;

                // Nafs logic dyal dates
                boolean isAfterStart = !g.getCreatedAt().isBefore(start); // >= start
                boolean isBeforeEnd = !g.getCreatedAt().isAfter(end);     // <= end

                return isAfterStart && isBeforeEnd;
            })
            // 2. Map to GasResponseDTO b Builder
            .map(g -> GasResponseDTO.builder()
                    .id(g.getId().toString())
                    .consumedGas(g.getConsumedGas()) // Awla g.getValue() 3la 7sab smiya f Entity
                    .createdAt(g.getCreatedAt())
                    .build())
            .collect(Collectors.toList());
}

    // 1. Njibo DATA kamla d9a w7da mn DB (Performance hsen mn anaka t3ayt DB f kol tour dyal boucle)
    List<Trash> allTrashes = repository.findAll();

    List<DailyTrashDTO> report = new ArrayList<>();
    LocalDateTime current = start;

    while (!current.isAfter(end)) {

        // Hado khashom ykono definin hna bach nsta3mlohom f Stream
        LocalDateTime dayStart = current.toLocalDate().atStartOfDay();
        LocalDateTime dayEnd = dayStart.plusDays(1);

        // 2. N-filtriw mn la liste li déjà 3ndna (In-Memory)
        Double totalWeight = allTrashes.stream()
                .filter(t -> {
                    if (t.getCreatedAt() == null) return false;
                    // Check wach Trash dial had nhar b ddbet
                    return !t.getCreatedAt().isBefore(dayStart) && 
                            t.getCreatedAt().isBefore(dayEnd);
                })
                .mapToDouble(Trash::getWight) // T2aked wach getWight wla getWeight f Entity
                .sum();

        Double dailyCarbon = calculateDailyFootPrint(totalWeight);

        report.add(DailyTrashDTO.builder()
                .date(current)
                .totalWeightKg(totalWeight)
                .carbonFootprintKg(dailyCarbon)
                .build());

        current = current.plusDays(1);
    }
    return report;
}

