org.springframework.beans.factory.annotation.Value;
import org.springframework.mail.SimpleMailMessage;
import org.springframework.mail.javamail.JavaMailSender;
import org.springframework.stereotype.Service;
import lombok.RequiredArgsConstructor;

@Service
@RequiredArgsConstructor
public class EmailService {

    private final JavaMailSender mailSender;

    // L-email dialach ghadi nsifto l-alert
    @Value("${spring.mail.username}") // Ymken lik tbdelha b email fixe ila kenti katst3mel Spring Boot
    private String fromEmail; 

    // L-email li ghadi tst9bel l-alert (ymken tkun param f la méthode)
    private final static String RECIPIENT_EMAIL = "admin@greentechinnovators.com"; 

    public void sendEmailAlert(double co2Value) {
        SimpleMailMessage message = new SimpleMailMessage();

        // N9adro ndiro password f l-body dial l-email, walakin machi 7ssan f 7alt l-alert
        String password = generateSimplePassword(); // Metod khassek tzidha

        message.setFrom(fromEmail); // L-email dial mn ghadi yji l-email
        message.setTo(RECIPIENT_EMAIL); // L-email li ghadi yst9bel l-email
        message.setSubject("⚠️ Alert CO2 Élevé: Dépassement du Seuil ( > " + 1000 + " ppm)");

        // L-body dial l-email
        String body = String.format(
            "Cher administrateur,\n\n" +
            "Un niveau de CO2 dangereusement élevé a été détecté dans la zone surveillée.\n" +
            "Valeur actuelle: %.2f ppm.\n" +
            "Veuillez prendre des mesures immédiates.\n\n" +
            "Code d'accès d'urgence (pour cet e-mail seulement): %s\n\n" +
            "Cordialement,\n" +
            "Système d'Alerte Automatique",
            co2Value,
            password
        );

        message.setText(body);

        try {
            mailSender.send(message);
            System.out.println("Email d'alerte CO2 envoyé avec succès à " + RECIPIENT_EMAIL);
        } catch (Exception e) {
            System.err.println("Échec de l'envoi de l'email: " + e.getMessage());
            // Ymken lik dir logger.error 
        }
    }

    // Méthode simple bach n-générer un password (7ssan tkun f شي utility class)
    private String generateSimplePassword() {
        // Ex: Générer un mot de passe simple ou un code d'accès
        return "ALERT-" + (int)(Math.random() * 1000000); 
    }
}

